 function snowArt(ctx,name,x,y,scale=1){if(!AI.Art?.ready)return;let cv=snowSprites.get(name);if(!cv){const size=AI.Art.size(name);if(!size[0])return;cv=document.createElement('canvas');cv.width=Math.ceil(size[0]/2);cv.height=Math.ceil(size[1]/2);const g=cv.getContext('2d');g.scale(.5,.5);AI.Art.draw(g,name,size[0]/2,size[1]);g.setTransform(1,0,0,1,0,0);const im=g.getImageData(0,0,cv.width,cv.height),original=new Uint8ClampedArray(im.data),W=cv.width;
   for(let yy=0;yy<cv.height;yy++)for(let xx=0;xx<W;xx++){const k=(yy*W+xx)*4;if(original[k+3]<128)continue;let exposed=false;for(let dy=1;dy<=3;dy++)if(yy-dy<0||original[((yy-dy)*W+xx)*4+3]<128)exposed=true;if((exposed||name.startsWith('tuftlow'))&&yy<cv.height*.92){const shade=hash(xx,yy,51);im.data[k]=207+shade*32;im.data[k+1]=226+shade*23;im.data[k+2]=237+shade*18;}}
   g.putImageData(im,0,0);snowSprites.set(name,cv);}ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(cv,Math.round(x-cv.width*scale),Math.round(y-cv.height*2*scale),cv.width*2*scale,cv.height*2*scale);ctx.restore();}
 function springsNear(x,y,r=900){if(outside()||special())return [];return nearCells(x,y,r+400).filter(c=>c.stream).map(c=>c.stream.source).filter(p=>Math.abs(p.x-x)<r+150&&Math.abs(p.y-y)<r+150);}
 function drawSpring(ctx,p){drawScenery(ctx,1,p.x,p.y-5,100);ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(Math.round(p.x/2)*2,Math.round(p.y/2)*2);polygon(ctx,[[-12,-6],[-10,-14],[-4,-20],[6,-18],[12,-10],[8,2],[-8,2]],'#101d2a');polygon(ctx,[[-5,-10],[0,-15],[5,-9],[4,3],[-4,3]],'#377186');ctx.fillStyle='#76afc1';ctx.fillRect(-2,-8,2,6);ctx.fillRect(0,-2,4,2);ctx.restore();}
 function drawPine(ctx,d){ellipse(ctx,d.x,d.y+2,28,10,'#243e5333');if(!drawScenery(ctx,0,d.x,d.y,160))snowArt(ctx,'fir_b',d.x,d.y,1.05);}
 function doorList(x,y,r=1000){if(outside()||special())return [{x:0,y:special()?550:180,target:'cave'}];return nearCells(x,y,r).flatMap(c=>[...(c.door?[c.door]:[]),...(c.ruin&&c.ruinAt?[{...c.ruinAt,target:c.ruin}]:[])]);}
 function drawDoor(ctx,d){const shape=outside()?2:d.target==='peak'?3:5;if(!drawScenery(ctx,shape,d.x,d.y+20,160)){AI.Art?.draw(ctx,'m_rock_a',d.x-35,d.y,{scale:1});AI.Art?.draw(ctx,'m_rock_a',d.x+35,d.y,{scale:1});}}
 const training=R.Training.drawables;R.Training.drawables=function(...a){const list=training.apply(this,a)||[],p=R.Game.player;if(!active()||!p)return list;const out=[...list,...springsNear(p.x,p.y,Math.max(R.Camera.w,R.Camera.h)).map(d=>({y:d.y-5,draw:ctx=>drawSpring(ctx,d)})),...cliffProps().map(d=>({y:d.y,draw:ctx=>drawScenery(ctx,1,d.x,d.y,100)})),...crystalsNear(p.x,p.y,Math.max(R.Camera.w,R.Camera.h)).map(c=>({y:c.y+5,draw:ctx=>crystal(ctx,c)})),...sceneProps().map(d=>({y:d.y,draw:ctx=>d.kind==='pine'?drawPine(ctx,d):drawScenery(ctx,4,d.x,d.y,65)})),...doorList(p.x,p.y).map(d=>({y:d.y,draw:ctx=>drawDoor(ctx,d)}))];if(special())out.push({y:65,draw:ctx=>temple(ctx,0,0,zone==='terapagos')});return out;};
 wrap(R.World,'drawGround',(_,ctx)=>drawGround(ctx));
 // All water effects share the same cached mask as the visible shoreline.
 let refl=null,rg=null,waterMask=null,wg=null,waterFx=null,fg=null;const contacts=[];
 function reflectionObjects(){const p=R.Game.player;if(!p)return {crystals:[],actors:[],trees:[]};const cs=crystalsNear(p.x,p.y,Math.max(R.Camera.w,R.Camera.h)+150).filter(c=>waterAt(c.x,c.y+20)||waterAt(c.x,c.y+75)||waterAt(c.x,c.y+130));const actors=[p,...R.EnemyMgr.drawables(R.Camera)].filter(e=>e&&!e.dead&&e.anim&&[6,22,40,60].some(dy=>waterAt(e.x,e.y+dy)));const trees=sceneProps().filter(d=>waterAt(d.x,d.y+30)||waterAt(d.x,d.y+90));return {crystals:cs,actors,trees};}
 function lightStrength(x,y,cs){let amount=0;for(const c of cs)amount=Math.max(amount,Math.max(0,1-Math.hypot(x-c.x,y-c.y)/c.radius));return outside()?1:amount;}
 function waterMotion(ctx,w,h,timeOverride){if(outside())return;const cam=R.Camera,[x0,y0,x1,y1]=view(),rw=Math.ceil((x1-x0)/2),rh=Math.ceil((y1-y0)/2),t=Number.isFinite(timeOverride)?timeOverride:performance.now()/1000;
  if(!refl){refl=document.createElement('canvas');waterMask=document.createElement('canvas');rg=refl.getContext('2d');wg=waterMask.getContext('2d');waterFx=document.createElement('canvas');fg=waterFx.getContext('2d');}if(refl.width!==rw||refl.height!==rh){refl.width=waterMask.width=waterFx.width=rw;refl.height=waterMask.height=waterFx.height=rh;}
  rg.setTransform(1,0,0,1,0,0);rg.clearRect(0,0,rw,rh);rg.globalAlpha=1;rg.globalCompositeOperation='source-over';rg.setTransform(.5,0,0,.5,-x0*.5,-y0*.5);rg.imageSmoothingEnabled=false;const objects=reflectionObjects(),nearLights=crystalsNear(cam.x,cam.y,Math.max(cam.w,cam.h)+300);
  // Never project a remote crystal into a pool: preserve the real object's position exactly.
  for(const c of objects.crystals){rg.save();rg.translate(c.x,c.y+4);rg.scale(1,-.9);rg.globalAlpha=.62;crystal(rg,{...c,x:0,y:0});rg.restore();}
  for(const e of objects.actors){rg.save();rg.translate(e.x,e.y+2);rg.scale(1,-.85);rg.globalAlpha=.45*lightStrength(e.x,e.y,nearLights);e.anim.draw(rg,0,0,{alpha:1});rg.restore();}
  for(const d of objects.trees){rg.save();rg.translate(d.x,d.y+3);rg.scale(1,-.9);drawPine(rg,{...d,x:0,y:0});rg.restore();}
  wg.setTransform(1,0,0,1,0,0);wg.clearRect(0,0,rw,rh);wg.setTransform(.5,0,0,.5,-x0*.5,-y0*.5);const layer=terrainLayer();wg.imageSmoothingEnabled=false;wg.drawImage(layer.mask,layer.x,layer.y,layer.w,layer.h);
  fg.setTransform(1,0,0,1,0,0);fg.globalAlpha=1;fg.globalCompositeOperation='source-over';fg.clearRect(0,0,rw,rh);fg.imageSmoothingEnabled=false;
  for(let row=0;row<rh;row+=2){const yy=y0+row*2,off=(Math.sin(yy*.075+t*2.3)*2.4+Math.sin(yy*.12-t*1.5)*1.3)/2;fg.drawImage(refl,0,row,rw,2,off,row,rw,2);}
  fg.setTransform(.5,0,0,.5,-x0*.5,-y0*.5);fg.setLineDash([]);
  for(const c of nearCells(cam.x,cam.y,Math.max(cam.w,cam.h))){if(!c.stream)continue;const pts=c.stream.pts;for(let i=0;i<36;i++){const u=(t*(.08+hash(i,c.cy,seed+502)*.08)+hash(i,c.cx,seed+501))%1,pos=u*(pts.length-1),k=Math.min(pts.length-2,Math.floor(pos)),a=pts[k],b=pts[k+1],f=pos-k,angle0=Math.atan2(b[1]-a[1],b[0]-a[0]),side=(hash(i,c.cx,seed+401)-.5)*c.stream.w*1.4,x=a[0]+(b[0]-a[0])*f-Math.sin(angle0)*side,y=a[1]+(b[1]-a[1])*f+Math.cos(angle0)*side;if(!waterAt(x,y))continue;const power=lightStrength(x,y,nearLights);if(power<.05)continue;const angle=Math.atan2(b[1]-a[1],b[0]-a[0]);fg.globalAlpha=.33*power*Math.min(1,u/.08,(1-u)/.08);fg.strokeStyle='#89bed0';fg.lineWidth=2;fg.beginPath();fg.moveTo(x-Math.cos(angle)*3,y-Math.sin(angle)*3);fg.lineTo(x+Math.cos(angle)*3,y+Math.sin(angle)*3);fg.stroke();}}
  for(const cell of nearCells(cam.x,cam.y,Math.max(cam.w,cam.h))){if(!cell.pool)continue;const p=cell.pool;for(let i=0;i<35;i++){const x=p.x+(hash(i,cell.cx,seed+402)-.5)*p.rx*2,y=p.y+(hash(i,cell.cy,seed+403)-.5)*p.ry*2;if(!waterAt(x,y))continue;const pulse=.5+.5*Math.sin(t*2+hash(i,cell.cx)*6);fg.globalAlpha=.22*pulse*lightStrength(x,y,nearLights);fg.fillStyle='#9cd6e5';fg.fillRect(Math.round((x+Math.sin(t+y*.1)*2)/2)*2,Math.round(y/2)*2,4+Math.floor(pulse*3)*2,2);}}
  for(let i=0;i<45;i++){const x=x0+hash(i,51)*(x1-x0),y=y0+hash(i,52)*(y1-y0),phase=(t*.6+hash(i,53)*4)%3;if(phase>1.1||!waterAt(x,y))continue;const power=lightStrength(x,y,nearLights);fg.globalAlpha=(1-phase/1.1)*.4*power;fg.strokeStyle='#bce7ef';fg.beginPath();fg.ellipse(x,y,2+phase*22,1+phase*9,0,0,Math.PI*2);fg.stroke();}
  for(const r of contacts){const age=t-r.t;if(age<0||age>.9)continue;fg.globalAlpha=(1-age/.9)*.4;fg.strokeStyle='#b5e7f0';fg.beginPath();fg.ellipse(r.x,r.y,4+age*23,2+age*10,0,0,Math.PI*2);fg.stroke();}  for(const p of springsNear(cam.x,cam.y,Math.max(cam.w,cam.h))){const k=(t*1.8+hash(p.x|0,p.y|0))%1;fg.globalAlpha=(1-k)*.5*lightStrength(p.x,p.y,nearLights);fg.strokeStyle='#a3dfeb';fg.beginPath();fg.ellipse(p.x,p.y+4,3+k*15,2+k*6,0,0,Math.PI*2);fg.stroke();}
  fg.setTransform(1,0,0,1,0,0);fg.globalAlpha=1;fg.globalCompositeOperation='destination-in';fg.drawImage(waterMask,0,0);fg.globalCompositeOperation='source-over';
  ctx.save();ctx.translate(-cam.left()*cam.scale,-cam.top()*cam.scale);ctx.scale(cam.scale,cam.scale);ctx.imageSmoothingEnabled=false;ctx.globalCompositeOperation='screen';ctx.globalAlpha=.85;ctx.drawImage(waterFx,x0,y0,rw*2,rh*2);ctx.restore();
 }

 let lm=null,lg=null;
 function lighting(ctx,w,h){const cam=R.Camera,t=performance.now()/1000;if(outside()){ctx.save();const gust=.5+.5*Math.sin(t*.38);ctx.fillStyle='#c3d8ed';ctx.globalAlpha=.07+gust*.04;ctx.fillRect(0,0,w,h);ctx.globalAlpha=1;
   for(let i=0;i<150;i++){const depth=.3+hash(i,3)*.7,xx=hash(i,1)*w+t*(28+gust*42)*depth-cam.x*.08*depth,yy=hash(i,2)*h+t*(16+hash(i,4)*24)*depth-cam.y*.08*depth,x=(xx%w+w)%w,y=(yy%h+h)%h;ctx.globalAlpha=.25+depth*.55;ctx.fillStyle='#fff';ctx.fillRect(Math.round(x/2)*2,Math.round(y/2)*2,depth>.7?3:2,2);}
   ctx.strokeStyle='#edf8ff';ctx.lineWidth=2;for(let i=0;i<7;i++){const phase=(t*.13+hash(i,9))%1;if(phase>.65)continue;ctx.globalAlpha=Math.sin(phase/.65*Math.PI)*.13;const x=phase*(w+420)-210,y=hash(i,10)*h+Math.sin(t*.6+i)*18;ctx.beginPath();for(let k=0;k<20;k++){const xx=x+k*8,yy=y+Math.sin(k*.15+i)*9;k?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy);}ctx.stroke();}ctx.restore();return;}
  if(!lm){lm=document.createElement('canvas');lg=lm.getContext('2d');}const q=3,lw=Math.ceil(w/q),lh=Math.ceil(h/q);if(lm.width!==lw||lm.height!==lh){lm.width=lw;lm.height=lh;}lg.globalCompositeOperation='source-over';lg.fillStyle='#000';lg.fillRect(0,0,lw,lh);lg.globalCompositeOperation='lighter';
  const cs=crystalsNear(cam.x,cam.y,Math.max(cam.w,cam.h)+300);if(special())cs.push({x:0,y:-100,variant:'rainbow',col:'#acf5ff',radius:420,rank:1,size:100});for(const c of cs){const colors=c.variant==='rainbow'?['#ff89d9','#78dcff','#a3ff8a']:c.variant==='fusion'?[c.col,c.col2]:[c.col];for(let i=0;i<colors.length;i++){const x=(c.x+(i-(colors.length-1)/2)*15-cam.left())*cam.scale/q,y=(c.y-15-cam.top())*cam.scale/q,r=c.radius*cam.scale/q,pulse=.84+.16*Math.sin(t*1.3+c.rank*7),g=lg.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,colors[i]+Math.round(255*pulse).toString(16).padStart(2,'0'));g.addColorStop(.35,colors[i]+'70');g.addColorStop(1,colors[i]+'00');lg.fillStyle=g;lg.fillRect(x-r,y-r,r*2,r*2);}}
  ctx.save();ctx.globalCompositeOperation='multiply';ctx.imageSmoothingEnabled=true;ctx.drawImage(lm,0,0,w,h);ctx.restore();waterMotion(ctx,w,h);
  ctx.save();ctx.fillStyle='#f2fbff';for(const c of cs){const phase=(t*.25+c.rank)%1;if(phase>.1)continue;const x=(c.x-cam.left())*cam.scale,y=(c.y-crystalMetrics(c).h*.75-cam.top())*cam.scale;ctx.globalAlpha=Math.sin(phase/.1*Math.PI)*.7;ctx.fillRect(Math.round(x)-3,Math.round(y),7,1);ctx.fillRect(Math.round(x),Math.round(y)-3,1,7);}ctx.restore();
 }
 wrap(R.Weather,'draw',(_,ctx,w,h)=>lighting(ctx,w,h));
 let moving=false,returnTo=null,stashed=false,cooldown=0;const fade=document.createElement('div');fade.style='position:fixed;inset:0;z-index:200;background:#000;opacity:0;pointer-events:none;transition:opacity .3s';document.body.append(fade);
 const discoveries=new Set();
 function discover(d){if(!['regigigas','terapagos'].includes(d.target))return;const id=seed+':'+d.target;if(discoveries.has(id))return;discoveries.add(id);const box=document.createElement('div');box.textContent="Oh, what's this?";box.style='position:fixed;left:50%;top:20%;transform:translateX(-50%);background:#111827ed;color:#fff;border:2px solid #a8baca;padding:12px 22px;font:16px monospace;z-index:201;pointer-events:none';document.body.append(box);setTimeout(()=>box.remove(),2800);}
 function travel(d){const p=R.Game.player;if(!active()||!p||moving||R.Coop?.active||window.PS_DENS?.raid)return false;const target=outside()||special()?'cave':d?.target||'peak';moving=true;discover(d||{});fade.style.opacity='1';R.Game.soloHold?.(true);setTimeout(()=>{try{if(target!=='cave'){returnTo=[d?.x??p.x,(d?.y??p.y)+90];R.EnemyMgr.stash();stashed=true;setZone(target);p.x=0;p.y=target==='peak'?-70:240;}else{R.EnemyMgr.clear();setZone('cave');if(stashed)R.EnemyMgr.restore();stashed=false;[p.x,p.y]=returnTo||[0,0];}p.__cpSafe=[p.x,p.y];contacts.length=0;R.Projectiles.clear();R.Hazards.clear();R.Combat.clearFields?.();R.Camera.x=p.x;R.Camera.y=p.y;cooldown=performance.now()+1800;}finally{moving=false;fade.style.opacity='0';R.Game.soloHold?.(false);}},320);return true;}

 setInterval(()=>{if(!active()||moving||R.Game.state!=='playing')return;const p=R.Game.player;if(!p)return;const now=performance.now()/1000;for(const e of [p,...R.EnemyMgr.all()]){if(!e||e.dead)continue;repair(e);const old=e.__cpWaterPos;if(old&&Math.hypot(e.x-old[0],e.y-old[1])>3&&waterAt(e.x,e.y)&&now-(e.__cpSplash||0)>(e===p ? 0.3 : 1.3)){e.__cpSplash=now;contacts.push({x:e.x,y:e.y,t:now});if(contacts.length>64)contacts.shift();if(e===p)AI.Ambience?.splash?.(e.x,e.y);}e.__cpWaterPos=[e.x,e.y];}if(performance.now()<cooldown)return;const d=doorList(p.x,p.y,700).find(d=>Math.hypot(p.x-d.x,p.y-d.y)<40);if(d)travel(d);},120);
 Object.assign(api,{travel,drawGround,drawGroundBase,light:lighting,drawWaterMotion:waterMotion,reflectionObjects,assetsReady:()=>crystalAtlas.complete&&crystalAtlas.naturalWidth>0&&sceneryAtlas.complete&&sceneryAtlas.naturalWidth>0&&sanctuaryAtlas.complete&&sanctuaryAtlas.naturalWidth>0,terrainSource:()=>provider?'gard-layouts-endless-cave':'connected-endless-fallback',doorList,drawTemple:temple,discoveries});
